99: default_read_func (
100:     exr_const_context_t         ctxt,
101:     void*                       userdata,
102:     void*                       buffer,
103:     uint64_t                    sz,
104:     uint64_t                    offset,
105:     exr_stream_error_func_ptr_t error_cb)
106: {
107:     int64_t                          rv, retsz = -1;
108:     struct _internal_exr_filehandle* fh     = userdata;
109:     int                              fd     = -1;
