136:     {
137:         if (error_cb)
138:             error_cb (
139:                 ctxt, EXR_ERR_INVALID_ARGUMENT, "Invalid file descriptor");
140:         return retsz;
141:     }
142: 
143: #if !CAN_USE_PREAD
144: #    if ILMTHREAD_THREADING_ENABLED
145:     pthread_mutex_lock (&(fh->mutex));
146: #    endif
147:     {
148: #    if defined __USE_LARGEFILE64
149:         uint64_t spos = (uint64_t) lseek64 (fd, (off64_t) offset, SEEK_SET);
150: #    else
