23: print_error_helper (
24:     exr_const_context_t         pf,
25:     exr_result_t                errcode,
26:     DWORD                       dw,
27:     exr_stream_error_func_ptr_t error_cb,
28:     const char*                 msg)
29: {
30:     LPVOID   lpMsgBuf;
31:     LPVOID   lpDisplayBuf;
32:     uint64_t bufsz = 0;
33: 
34:     FormatMessage (
35:         FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_FROM_SYSTEM |
36:             FORMAT_MESSAGE_IGNORE_INSERTS,
37:         NULL,
38:         dw,
39:         MAKELANGID (LANG_NEUTRAL, SUBLANG_DEFAULT),
40:         (LPTSTR) &lpMsgBuf,
41:         0,
42:         NULL);
43: 
44:     bufsz =
45:         (lstrlen ((LPCTSTR) lpMsgBuf) + strlen (msg) +
46:          20); /* extra for format string */
47: 
48:     lpDisplayBuf = (LPVOID) LocalAlloc (LMEM_ZEROINIT, bufsz * sizeof (TCHAR));
49: 
50:     if (FAILED (StringCchPrintf (
51:             (LPTSTR) lpDisplayBuf,
52:             bufsz,
53:             TEXT ("%s: (%" PRId64 ") %s"),
54:             msg,
55:             (int64_t) dw,
56:             lpMsgBuf)))
57:     {
58:         return pf->print_error (
59:             pf, EXR_ERR_OUT_OF_MEMORY, "Unable to format message print");
60:     }
61: 
62:     if (error_cb)
63:         error_cb (pf, errcode, "%s", (const char*) lpDisplayBuf);
64:     else
65:         pf->print_error (pf, errcode, "%s", (const char*) lpDisplayBuf);
66: 
67:     LocalFree (lpMsgBuf);
68:     LocalFree (lpDisplayBuf);
69: 
70:     return errcode;
71: }
