374: handleExceptionsSetInRegisters ()
375: {
376:     if (fpeHandler == 0) return;
377: 
378:     int mask = FpuControl::getExceptionMask ();
379: 
380:     int exc = FpuControl::getExceptions ();
381: 
382:     if (!(mask & FpuControl::DIVZERO_EXC) && (exc & FpuControl::DIVZERO_EXC))
383:     {
384:         fpeHandler (IEEE_DIVZERO, "Floating-point division by zero.");
385:         return;
386:     }
387: 
388:     if (!(mask & FpuControl::OVERFLOW_EXC) && (exc & FpuControl::OVERFLOW_EXC))
389:     {
390:         fpeHandler (IEEE_OVERFLOW, "Floating-point overflow.");
391:         return;
392:     }
393: 
394:     if (!(mask & FpuControl::UNDERFLOW_EXC) &&
395:         (exc & FpuControl::UNDERFLOW_EXC))
396:     {
397:         fpeHandler (IEEE_UNDERFLOW, "Floating-point underflow.");
398:         return;
399:     }
400: 
401:     if (!(mask & FpuControl::INEXACT_EXC) && (exc & FpuControl::INEXACT_EXC))
402:     {
403:         fpeHandler (IEEE_INEXACT, "Inexact floating-point result.");
404:         return;
405:     }
406: 
407:     if (!(mask & FpuControl::INVALID_EXC) && (exc & FpuControl::INVALID_EXC))
408:     {
409:         fpeHandler (IEEE_INVALID, "Invalid floating-point operation.");
410:         return;
411:     }
